{
  "items": [
    {
      "name": "Real.exists_int_int_abs_mul_sub_le",
      "module_name": "Mathlib.NumberTheory.DiophantineApproximation.Basic",
      "kind": "theorem",
      "type": "∀ (ξ : ℝ) {n : ℕ}, 0 < n → ∃ j k, 0 < k ∧ k ≤ ↑n ∧ |↑k * ξ - ↑j| ≤ 1 / (↑n + 1)"
    },
    {
      "name": "Liouville.exists_one_le_pow_mul_dist",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.Basic",
      "kind": "theorem",
      "type": "∀ {Z : Type u_1} {N : Type u_2} {R : Type u_3} [inst : PseudoMetricSpace R] {d : N → ℝ} {j : Z → N → R} {f : R → R}\n  {α : R} {ε M : ℝ},\n  (∀ (a : N), 1 ≤ d a) →\n    0 < ε →\n      (∀ ⦃y : R⦄, y ∈ Metric.closedBall α ε → dist (f α) (f y) ≤ dist α y * M) →\n        (∀ ⦃z : Z⦄ ⦃a : N⦄, j z a ∈ Metric.closedBall α ε → 1 ≤ d a * dist (f α) (f (j z a))) →\n          ∃ A, 0 < A ∧ ∀ (z : Z) (a : N), 1 ≤ d a * (dist α (j z a) * A)"
    },
    {
      "name": "tendsto_nat_ceil_mul_div_atTop",
      "module_name": "Mathlib.Analysis.SpecificLimits.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u_4} [inst : TopologicalSpace R] [inst_1 : Field R] [inst_2 : LinearOrder R]\n  [inst_3 : IsStrictOrderedRing R] [OrderTopology R] [inst_5 : FloorRing R] {a : R},\n  0 ≤ a → Filter.Tendsto (fun x => ↑⌈a * x⌉₊ / x) Filter.atTop (nhds a)"
    },
    {
      "name": "Real.exists_nat_abs_mul_sub_round_le",
      "module_name": "Mathlib.NumberTheory.DiophantineApproximation.Basic",
      "kind": "theorem",
      "type": "∀ (ξ : ℝ) {n : ℕ}, 0 < n → ∃ k, 0 < k ∧ k ≤ n ∧ |↑k * ξ - ↑(round (↑k * ξ))| ≤ 1 / (↑n + 1)"
    },
    {
      "name": "wellApproximable",
      "module_name": "Mathlib.NumberTheory.WellApproximable",
      "kind": "definition",
      "type": "(A : Type u_1) → [SeminormedGroup A] → (ℕ → ℝ) → Set A"
    },
    {
      "name": "SeparationQuotient.mk_nsmul",
      "module_name": "Mathlib.Topology.Algebra.SeparationQuotient.Basic",
      "kind": "theorem",
      "type": "∀ {M : Type u_1} [inst : TopologicalSpace M] [inst_1 : AddMonoid M] [inst_2 : ContinuousAdd M] (x : M) (n : ℕ),\n  SeparationQuotient.mk (n • x) = n • SeparationQuotient.mk x"
    },
    {
      "name": "Rat.den_le_and_le_num_le_of_sub_lt_one_div_den_sq",
      "module_name": "Mathlib.NumberTheory.DiophantineApproximation.Basic",
      "kind": "theorem",
      "type": "∀ {ξ q : ℚ}, |ξ - q| < 1 / ↑q.den ^ 2 → q.den ≤ ξ.den ∧ ⌈ξ * ↑q.den⌉ - 1 ≤ q.num ∧ q.num ≤ ⌊ξ * ↑q.den⌋ + 1"
    },
    {
      "name": "Real.exists_rat_abs_sub_le_and_den_le",
      "module_name": "Mathlib.NumberTheory.DiophantineApproximation.Basic",
      "kind": "theorem",
      "type": "∀ (ξ : ℝ) {n : ℕ}, 0 < n → ∃ q, |ξ - ↑q| ≤ 1 / ((↑n + 1) * ↑q.den) ∧ q.den ≤ n"
    }
  ]
}
